    private static final Map<String, Integer> KEY_INDEX = new HashMap<>();
    private static final Map<String, int[]> NAME_INDEX = new HashMap<>();
    static {
        for (int i = 0; i < COUNT; i++) KEY_INDEX.put(KEY[i], i);
    }
    static {
        Map<String, java.util.List<Integer>> acc = new HashMap<>();
        for (int i = 0; i < COUNT; i++)
            for (String a : ALIASES[i]) {
                String k = a.toLowerCase(java.util.Locale.US).trim();
                java.util.List<Integer> l = acc.get(k);
                if (l == null) { l = new java.util.ArrayList<>(); acc.put(k, l); }
                if (!l.contains(i)) l.add(i);
            }
        for (Map.Entry<String, java.util.List<Integer>> en : acc.entrySet()) {
            int[] arr = new int[en.getValue().size()];
            for (int j = 0; j < arr.length; j++) arr[j] = en.getValue().get(j);
            NAME_INDEX.put(en.getKey(), arr);
        }
    }
    public static int indexOfKey(String key) { Integer i = KEY_INDEX.get(key); return i == null ? -1 : i; }
    /** All entry indices a name/alias resolves to (empty when unknown);
     *  size>1 = ambiguous (e.g. LADSPA "Flanger" vs LV2 "Gx_flanger"). */
    public static int[] indicesForName(String name) {
        if (name == null) return new int[0];
        int[] r = NAME_INDEX.get(name.toLowerCase(java.util.Locale.US).trim());
        return r == null ? new int[0] : r;
    }
